import osimport jsonfrom sqlalchemy import create_engine, Column, Integer, String, Boolean, DateTime, Textfrom sqlalchemy.orm import sessionmaker, declarative_basefrom datetime import datetimeDB_PATH = os.getenv("DB_PATH", "/data/tenants.db")DATABASE_URL = f"sqlite:///{DB_PATH}"engine = create_engine(DATABASE_URL, connect_args={"check_same_thread": False})SessionLocal = sessionmaker(bind=engine, autoflush=False, autocommit=False)Base = declarative_base()class Tenant(Base):    __tablename__ = "tenants"    id = Column(Integer, primary_key=True, autoincrement=True)    code = Column(String(50), unique=True, nullable=False, index=True)    name = Column(String(200), nullable=False)    type = Column(String(50), nullable=False, default="barbershop")    address = Column(String(300), nullable=True)    phone = Column(String(50), nullable=True)    onec_url = Column(String(300), nullable=False)    onec_user = Column(String(100), nullable=True)    onec_password = Column(String(100), nullable=True)    is_active = Column(Boolean, default=True)    subscription_until = Column(DateTime, nullable=True)    created_at = Column(DateTime, default=datetime.utcnow)class Reminder(Base):    __tablename__ = "reminders"    id = Column(Integer, primary_key=True, autoincrement=True)    user_id = Column(Integer, nullable=False, index=True)    tenant_code = Column(String(50), nullable=False)    employee_name = Column(String(200), nullable=False)    date = Column(String(20), nullable=False)    time = Column(String(10), nullable=False)    reminded = Column(Boolean, default=False, index=True)    created_at = Column(DateTime, default=datetime.utcnow)class UserState(Base):    __tablename__ = "user_states"    user_id = Column(Integer, primary_key=True)    data = Column(Text, nullable=False)    updated_at = Column(DateTime, default=datetime.utcnow)def init_db():    os.makedirs(os.path.dirname(DB_PATH), exist_ok=True)    Base.metadata.create_all(bind=engine)    session = SessionLocal()    try:        if session.query(Tenant).count() == 0:            t1 = Tenant(                code="barber_main",                name="Парикмахерская на Ленина",                type="barbershop",                address="г. Москва, ул. Ленина, д. 1",                phone="+7 (999) 123-45-67",                onec_url=os.getenv("ONEC_BASE_URL", "http://178.21.11.91/booking/hs/booking"),                onec_user=os.getenv("ONEC_USER"),                onec_password=os.getenv("ONEC_PASSWORD"),                is_active=True,            )            t2 = Tenant(                code="barber_center",                name="Парикмахерская в центре",                type="barbershop",                address="г. Москва, ул. Тверская, д. 10",                phone="+7 (999) 765-43-21",                onec_url="http://178.21.11.91/booking2/hs/booking",                onec_user=os.getenv("ONEC_USER"),                onec_password=os.getenv("ONEC_PASSWORD"),                is_active=True,            )            session.add_all([t1, t2])            session.commit()            print("✅ Добавлены тестовые тенанты: barber_main, barber_center")    finally:        session.close()# ===== Tenants =====def get_tenant_by_code(code: str):    session = SessionLocal()    try:        return session.query(Tenant).filter(            Tenant.code == code, Tenant.is_active == True        ).first()    finally:        session.close()def get_all_tenants():    session = SessionLocal()    try:        return session.query(Tenant).filter(Tenant.is_active == True).all()    finally:        session.close()# ===== Reminders =====def save_reminder(user_id: int, tenant_code: str, employee_name: str, date_str: str, time_str: str):    session = SessionLocal()    try:        r = Reminder(            user_id=user_id,            tenant_code=tenant_code,            employee_name=employee_name,            date=date_str,            time=time_str,            reminded=False,        )        session.add(r)        session.commit()        print(f"✅ Напоминание сохранено: user={user_id}, {date_str} {time_str}")    finally:        session.close()def get_pending_reminders():    session = SessionLocal()    try:        return session.query(Reminder).filter(Reminder.reminded == False).all()    finally:        session.close()def mark_reminded(reminder_id: int):    session = SessionLocal()    try:        r = session.query(Reminder).filter(Reminder.id == reminder_id).first()        if r:            r.reminded = True            session.commit()    finally:        session.close()# ===== User states (вместо Redis) =====def db_get_state(user_id: int) -> dict:    session = SessionLocal()    try:        row = session.query(UserState).filter(UserState.user_id == user_id).first()        return json.loads(row.data) if row else {}    finally:        session.close()def db_set_state(user_id: int, state: dict):    session = SessionLocal()    try:        row = session.query(UserState).filter(UserState.user_id == user_id).first()        data = json.dumps(state, ensure_ascii=False)        if row:            row.data = data            row.updated_at = datetime.utcnow()        else:            session.add(UserState(user_id=user_id, data=data))        session.commit()    finally:        session.close()def db_del_state(user_id: int):    session = SessionLocal()    try:        session.query(UserState).filter(UserState.user_id == user_id).delete()        session.commit()    finally:        session.close()